#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>

#define LEFT_R_EN   27
#define LEFT_L_EN   14
#define LEFT_RPWM   25
#define LEFT_LPWM   26

#define RIGHT_R_EN  33
#define RIGHT_L_EN  32
#define RIGHT_RPWM  18
#define RIGHT_LPWM  19

#define PWM_FREQ 20000
#define PWM_RES 8

// Increased from 5 seconds to 15 seconds
#define COMMUNICATION_TIMEOUT 15000

unsigned long lastCommandTime = 0;

uint8_t controllerAddress[6];
bool controllerFound = false;

struct CommandPacket {
  char command;
  uint8_t speed;
};


// ==============================
// MOTOR FUNCTIONS
// ==============================

void stopMotors() {
  ledcWrite(LEFT_RPWM, 0);
  ledcWrite(LEFT_LPWM, 0);
  ledcWrite(RIGHT_RPWM, 0);
  ledcWrite(RIGHT_LPWM, 0);
}

void forward(uint8_t speed) {
  ledcWrite(LEFT_RPWM, speed);
  ledcWrite(LEFT_LPWM, 0);

  ledcWrite(RIGHT_RPWM, speed);
  ledcWrite(RIGHT_LPWM, 0);
}

void reverse(uint8_t speed) {
  ledcWrite(LEFT_RPWM, 0);
  ledcWrite(LEFT_LPWM, speed);

  ledcWrite(RIGHT_RPWM, 0);
  ledcWrite(RIGHT_LPWM, speed);
}

void turnLeft(uint8_t speed) {
  ledcWrite(LEFT_RPWM, 0);
  ledcWrite(LEFT_LPWM, speed);

  ledcWrite(RIGHT_RPWM, speed);
  ledcWrite(RIGHT_LPWM, 0);
}

void turnRight(uint8_t speed) {
  ledcWrite(LEFT_RPWM, speed);
  ledcWrite(LEFT_LPWM, 0);

  ledcWrite(RIGHT_RPWM, 0);
  ledcWrite(RIGHT_LPWM, speed);
}


// ==============================
// ADD CONTROLLER
// ==============================

bool addController() {

  if (esp_now_is_peer_exist(controllerAddress)) {
    return true;
  }

  esp_now_peer_info_t peerInfo = {};

  memcpy(peerInfo.peer_addr, controllerAddress, 6);

  peerInfo.channel = 1;
  peerInfo.encrypt = false;

  return esp_now_add_peer(&peerInfo) == ESP_OK;
}


// ==============================
// RECEIVE DATA
// ==============================

void onDataReceive(
  const esp_now_recv_info_t *info,
  const uint8_t *data,
  int len
) {

  // Controller discovery
  if (len >= 5 && memcmp(data, "HELLO", 5) == 0) {

    memcpy(controllerAddress, info->src_addr, 6);

    controllerFound = addController();

    // Reset communication timer whenever
    // the controller announces itself
    lastCommandTime = millis();

    if (controllerFound) {

      Serial.println();
      Serial.println("==============================");
      Serial.println("CONTROLLER FOUND!");
      Serial.println("==============================");

      const char reply[] = "CAR";

      esp_now_send(
        controllerAddress,
        (uint8_t *)reply,
        sizeof(reply)
      );
    }

    return;
  }


  // Ignore commands until controller is found
  if (!controllerFound) {
    return;
  }


  // Check packet size
  if (len != sizeof(CommandPacket)) {
    return;
  }


  CommandPacket packet;

  memcpy(
    &packet,
    data,
    sizeof(packet)
  );


  // Every valid command resets the timeout
  lastCommandTime = millis();


  // Execute command
  switch (packet.command) {

    case 'F':
      forward(packet.speed);

      Serial.print("FORWARD  ");
      Serial.println(packet.speed);
      break;


    case 'B':
      reverse(packet.speed);

      Serial.print("REVERSE  ");
      Serial.println(packet.speed);
      break;


    case 'L':
      turnLeft(packet.speed);

      Serial.print("LEFT  ");
      Serial.println(packet.speed);
      break;


    case 'R':
      turnRight(packet.speed);

      Serial.print("RIGHT  ");
      Serial.println(packet.speed);
      break;


    case 'S':
      stopMotors();

      Serial.println("STOP");
      break;


    default:
      stopMotors();
      break;
  }
}


// ==============================
// SETUP
// ==============================

void setup() {

  Serial.begin(115200);


  // Enable pins
  pinMode(LEFT_R_EN, OUTPUT);
  pinMode(LEFT_L_EN, OUTPUT);

  pinMode(RIGHT_R_EN, OUTPUT);
  pinMode(RIGHT_L_EN, OUTPUT);


  digitalWrite(LEFT_R_EN, HIGH);
  digitalWrite(LEFT_L_EN, HIGH);

  digitalWrite(RIGHT_R_EN, HIGH);
  digitalWrite(RIGHT_L_EN, HIGH);


  // PWM
  ledcAttach(
    LEFT_RPWM,
    PWM_FREQ,
    PWM_RES
  );

  ledcAttach(
    LEFT_LPWM,
    PWM_FREQ,
    PWM_RES
  );

  ledcAttach(
    RIGHT_RPWM,
    PWM_FREQ,
    PWM_RES
  );

  ledcAttach(
    RIGHT_LPWM,
    PWM_FREQ,
    PWM_RES
  );


  // Make absolutely sure motors start stopped
  stopMotors();


  // WiFi / ESP-NOW
  WiFi.mode(WIFI_STA);

  esp_wifi_set_channel(
    1,
    WIFI_SECOND_CHAN_NONE
  );


  Serial.println();
  Serial.println("==============================");
  Serial.println("ESP32 CAR");
  Serial.println("==============================");

  Serial.print("Car MAC: ");
  Serial.println(WiFi.macAddress());


  // Start ESP-NOW
  if (esp_now_init() != ESP_OK) {

    Serial.println("ESP-NOW FAILED!");

    stopMotors();

    while (true) {
      delay(1000);
    }
  }


  esp_now_register_recv_cb(onDataReceive);


  Serial.println("ESP-NOW READY");
  Serial.println("Waiting for controller...");


  lastCommandTime = millis();
}


// ==============================
// MAIN LOOP
// ==============================

void loop() {

  // If controller has been silent for 15 seconds,
  // stop the motors and wait for it again.

  if (
    controllerFound &&
    millis() - lastCommandTime > COMMUNICATION_TIMEOUT
  ) {

    stopMotors();

    controllerFound = false;

    Serial.println();
    Serial.println("CONTROLLER LOST - STOPPING");
    Serial.println("Waiting for controller...");
  }


  delay(10);
}
